. deploy/lib.sh
# Diagnóstico (só leitura) do total vendido de outubro/2026 na tela de Comissões
Q() { echo "## $1"; sql -At -F ' | ' -c "$2"; }
DR="coalesce(data_conclusao::date, data_faturamento::date, nullif(dia::text,'')::date, created_at::date)"
Q "total linhas ofs" "select count(*), count(*) filter (where deleted_at is not null) from public.ofs;"
Q "criterio atual (concluida, sem deleted, data em out)" "select count(*), round(sum(coalesce(valor_total,0))::numeric,2) from public.ofs where deleted_at is null and status ilike '%conclu%' and status not ilike '%cancel%' and $DR >= '2026-10-01' and $DR < '2026-11-01';"
Q "status de todas as OFs com data de referencia em out" "select status, count(*), round(sum(coalesce(valor_total,0))::numeric,2) from public.ofs where $DR >= '2026-10-01' and $DR < '2026-11-01' group by 1 order by 2 desc;"
Q "OFs CRIADAS (lancadas) em out por status" "select status, count(*), round(sum(coalesce(valor_total,0))::numeric,2) from public.ofs where created_at >= '2026-10-01 03:00+00' and created_at < '2026-11-01 03:00+00' and deleted_at is null group by 1 order by 2 desc;"
Q "concluidas em out com deleted_at" "select count(*), round(sum(coalesce(valor_total,0))::numeric,2) from public.ofs where deleted_at is not null and status ilike '%conclu%' and $DR >= '2026-10-01' and $DR < '2026-11-01';"
Q "concluidas em out com valor_total vazio/zero" "select count(*), round(sum(coalesce(qtd,quantidade,0)*coalesce(valor_unitario,preco,0))::numeric,2) from public.ofs where deleted_at is null and status ilike '%conclu%' and $DR >= '2026-10-01' and $DR < '2026-11-01' and coalesce(valor_total,0)=0;"
Q "concluidas em out onde valor_total difere de qtd*preco (>1 real)" "select count(*), round(sum(coalesce(qtd,quantidade,0)*coalesce(valor_unitario,preco,0) - coalesce(valor_total,0))::numeric,2) from public.ofs where deleted_at is null and status ilike '%conclu%' and $DR >= '2026-10-01' and $DR < '2026-11-01' and abs(coalesce(qtd,quantidade,0)*coalesce(valor_unitario,preco,0) - coalesce(valor_total,0)) > 1;"
Q "qual campo de data decide (concluidas em out)" "select case when data_conclusao is not null then 'data_conclusao' when data_faturamento is not null then 'data_faturamento' when dia is not null then 'dia' else 'created_at' end, count(*) from public.ofs where deleted_at is null and status ilike '%conclu%' and $DR >= '2026-10-01' and $DR < '2026-11-01' group by 1;"
Q "concluidas com data_conclusao em out mas criterio joga para outro mes" "select count(*), round(sum(coalesce(valor_total,0))::numeric,2) from public.ofs where deleted_at is null and status ilike '%conclu%' and data_conclusao >= '2026-10-01' and data_conclusao < '2026-11-01' and not ($DR >= '2026-10-01' and $DR < '2026-11-01');"
Q "por mes (criterio atual) 2026" "select to_char($DR,'YYYY-MM'), count(*), round(sum(coalesce(valor_total,0))::numeric,2) from public.ofs where deleted_at is null and status ilike '%conclu%' and status not ilike '%cancel%' and $DR >= '2026-01-01' group by 1 order by 1;"
Q "clientes TESTE (excluidos) em out" "select count(*), round(sum(coalesce(valor_total,0))::numeric,2) from public.ofs where deleted_at is null and status ilike '%conclu%' and $DR >= '2026-10-01' and $DR < '2026-11-01' and upper(coalesce(clinome,cliente_nome,cliente,'')) like '%TESTE%';"
Q "maiores valores concluidos em out" "select of, coalesce(clinome,cliente_nome), qtd, valor_total from public.ofs where deleted_at is null and status ilike '%conclu%' and $DR >= '2026-10-01' and $DR < '2026-11-01' order by valor_total desc nulls last limit 8;"
